export function initialize(element, dotNetRef, timeoutSeconds) {
    const timeoutMs = timeoutSeconds * 1000;
    let timerId = null;
    let isIdle = false;

    const events = ["mousemove", "keydown", "click", "scroll", "touchstart"];

    function resetTimer() {
        if (isIdle) {
            isIdle = false;
            dotNetRef.invokeMethodAsync("OnActiveCallback");
        }
        clearTimeout(timerId);
        timerId = setTimeout(() => {
            isIdle = true;
            dotNetRef.invokeMethodAsync("OnIdleCallback");
        }, timeoutMs);
    }

    for (const evt of events) {
        element.addEventListener(evt, resetTimer, { passive: true });
    }

    // Start the initial timer
    timerId = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync("OnIdleCallback");
    }, timeoutMs);

    state = { element, events, resetTimer, timerId };
}

export function dispose() {
    if (!state) return;
    const { element, events, resetTimer, timerId } = state;
    clearTimeout(timerId);
    for (const evt of events) {
        element.removeEventListener(evt, resetTimer);
    }
    state = null;
}

